using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Admin;
public sealed class UserBarnAssignmentService { private readonly Database _db; public UserBarnAssignmentService(Database db)=>_db=db; public async Task ReplaceAsync(Guid userId,IEnumerable<Guid> barnIds,Guid actor){var ids=barnIds.Distinct().ToList();await using var cn=await _db.OpenAsync();await using var tx=await cn.BeginTransactionAsync();await using(var d=new NpgsqlCommand("delete from user_barn_assignments where user_id=@u",cn,tx)){d.Parameters.AddWithValue("u",userId);await d.ExecuteNonQueryAsync();}foreach(var b in ids){await using var i=new NpgsqlCommand("insert into user_barn_assignments(user_id,barn_id) values(@u,@b)",cn,tx);i.Parameters.AddWithValue("u",userId);i.Parameters.AddWithValue("b",b);await i.ExecuteNonQueryAsync();}await using(var a=new NpgsqlCommand("insert into audit_log(user_id,event_type,entity_type,entity_id,details) values(@a,'BARN_ASSIGNMENT_CHANGED','app_users',@u,jsonb_build_object('barn_count',@n))",cn,tx)){a.Parameters.AddWithValue("a",actor);a.Parameters.AddWithValue("u",userId.ToString());a.Parameters.AddWithValue("n",ids.Count);await a.ExecuteNonQueryAsync();}await tx.CommitAsync();} }
